CREATE TYPE "Role" AS ENUM ('CUSTOMER','ADMIN');
CREATE TYPE "OrderStatus" AS ENUM ('DRAFT','PENDING','REVIEW','APPROVED','RUNNING','PAUSED','COMPLETED','CANCELED','FAILED');
CREATE TYPE "TicketStatus" AS ENUM ('OPEN','WAITING','RESOLVED','CLOSED');
CREATE TYPE "LedgerType" AS ENUM ('DEPOSIT','ORDER_CHARGE','REFUND','ADJUSTMENT');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'CUSTOMER',"disabledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Service" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"priceCents" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"providerCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"serviceId" TEXT NOT NULL,"targetUrl" TEXT NOT NULL,"brief" TEXT NOT NULL,"budgetCents" INTEGER NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Order_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id"), CONSTRAINT "Order_serviceId_fkey" FOREIGN KEY("serviceId") REFERENCES "Service"("id"));
CREATE TABLE "LedgerEntry" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"type" "LedgerType" NOT NULL,"amountCents" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'USD',"reference" TEXT,"idempotencyKey" TEXT UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LedgerEntry_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id"));
CREATE TABLE "Ticket" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"subject" TEXT NOT NULL,"status" "TicketStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Ticket_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id"));
CREATE TABLE "TicketMessage" ("id" TEXT PRIMARY KEY,"ticketId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TicketMessage_ticketId_fkey" FOREIGN KEY("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE);
CREATE TABLE "ApiKey" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"prefix" TEXT NOT NULL,"secretHash" TEXT NOT NULL,"lastUsedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ApiKey_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id"));
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"actorId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Job" ("id" TEXT PRIMARY KEY,"kind" TEXT NOT NULL,"payload" JSONB NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"runAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Order_userId_createdAt_idx" ON "Order"("userId","createdAt"); CREATE INDEX "LedgerEntry_userId_createdAt_idx" ON "LedgerEntry"("userId","createdAt"); CREATE INDEX "TicketMessage_ticketId_createdAt_idx" ON "TicketMessage"("ticketId","createdAt"); CREATE INDEX "AuditLog_actorId_createdAt_idx" ON "AuditLog"("actorId","createdAt"); CREATE INDEX "Job_completedAt_runAt_idx" ON "Job"("completedAt","runAt");
